export function walkthroughStep(step, language) {
  const entry = WALKTHROUGH_TEXT[step.id] || GENERATED_WALKTHROUGH_TEXT[step.id];
  if (entry?.[0] === step.text_hash) return entry[{ es: 1, zh: 2 }[language]] ?? step.text;
  return step.text;
}
